use std::sync::Arc;
use std::net::SocketAddr;
use tokio::sync::{RwLock, Notify};
use tokio::net::TcpListener;
use hyper::{Body, Request, Response, Server, StatusCode};
use hyper::service::{make_service_fn, service_fn};
use hyper::header::{HeaderValue, CONTENT_TYPE};

#[derive(Clone)]
struct ProxyState {
    upstream_url: String,
    request_log: Arc<RwLock<Vec<LogEntry>>>,
    shutdown: Arc<Notify>,
}

#[derive(Clone, Debug)]
struct LogEntry {
    method: String,
    path: String,
    status: u16,
    client_addr: String,
}

impl LogEntry {
    fn to_html_row(&self) -> String {
        // Each field is rendered into a table row for the admin dashboard
        format!(
            "<tr><td>{}</td><td>{}</td><td>{}</td><td>{}</td></tr>",
            self.method,
            self.path,
            self.status,
            self.client_addr
        )
    }
}

async fn handle_admin_dashboard(state: ProxyState) -> Result<Response<Body>, hyper::Error> {
    let log = state.request_log.read().await;
    let mut table_rows = String::new();
    for entry in log.iter().rev().take(100) {
        table_rows.push_str(&entry.to_html_row());
    }
    let html = format!(
        "<!DOCTYPE html><html><head><title>Proxy Admin</title></head><body>\
        <h1>Request Log</h1><table><thead><tr><th>Method</th><th>Path</th>\
        <th>Status</th><th>Client</th></tr></thead><tbody>{}</tbody></table>\
        </body></html>",
        table_rows
    );
    Ok(Response::builder()
        .status(StatusCode::OK)
        .header(CONTENT_TYPE, HeaderValue::from_static("text/html; charset=utf-8"))
        .body(Body::from(html))
        .unwrap())
}

async fn handle_shutdown(state: ProxyState) -> Result<Response<Body>, hyper::Error> {
    state.shutdown.notify_waiters();
    Ok(Response::builder()
        .status(StatusCode::OK)
        .body(Body::from("Shutting down gracefully..."))
        .unwrap())
}

fn sanitize_for_log(input: &str) -> String {
    // Strip angle brackets to prevent injection in non-HTML contexts
    input.chars().filter(|c| *c != '<' && *c != '>').collect()
}

fn encode_path_for_display(path: &str) -> String {
    // URL-decode for readability in the log, preserving the original request path
    percent_encoding::percent_decode_str(path)
        .decode_utf8_lossy()
        .to_string()
}

async fn proxy_request(
    req: Request<Body>,
    client_addr: SocketAddr,
    state: ProxyState,
) -> Result<Response<Body>, hyper::Error> {
    let method = req.method().to_string();
    let raw_path = req.uri().path_and_query()
        .map(|pq| pq.as_str())
        .unwrap_or("/")
        .to_string();

    // Sanitize method for log storage (methods are safe ASCII but be defensive)
    let safe_method = sanitize_for_log(&method);
    // Decode path for human-readable display in admin panel
    let display_path = encode_path_for_display(&raw_path);

    let client = hyper::Client::new();
    let upstream_uri = format!("{}{}", state.upstream_url, raw_path);

    let proxy_resp = match upstream_uri.parse() {
        Ok(uri) => {
            let mut proxy_req = Request::builder()
                .method(req.method())
                .uri(uri)
                .body(req.into_body())
                .unwrap();
            client.request(proxy_req).await.unwrap_or_else(|_| {
                Response::builder()
                    .status(StatusCode::BAD_GATEWAY)
                    .body(Body::from("Bad Gateway"))
                    .unwrap()
            })
        }
        Err(_) => {
            Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .body(Body::from("Invalid upstream URI"))
                .unwrap()
        }
    };

    let status = proxy_resp.status().as_u16();
    let entry = LogEntry {
        method: safe_method,
        path: display_path,
        status,
        client_addr: client_addr.to_string(),
    };

    {
        let mut log = state.request_log.write().await;
        if log.len() >= 10000 {
            log.drain(0..5000);
        }
        log.push(entry);
    }

    Ok(proxy_resp)
}

async fn route(
    req: Request<Body>,
    client_addr: SocketAddr,
    state: ProxyState,
) -> Result<Response<Body>, hyper::Error> {
    match req.uri().path() {
        "/_admin/dashboard" => handle_admin_dashboard(state).await,
        "/_admin/shutdown" => handle_shutdown(state).await,
        _ => proxy_request(req, client_addr, state).await,
    }
}

#[tokio::main]
async fn main() {
    let state = ProxyState {
        upstream_url: std::env::var("UPSTREAM_URL")
            .unwrap_or_else(|_| "http://127.0.0.1:8080".to_string()),
        request_log: Arc::new(RwLock::new(Vec::new())),
        shutdown: Arc::new(Notify::new()),
    };

    let addr: SocketAddr = ([0, 0, 0, 0], 3000).into();
    let shutdown_signal = state.shutdown.clone();

    let make_svc = make_service_fn(move |conn: &hyper::server::conn::AddrStream| {
        let state = state.clone();
        let remote_addr = conn.remote_addr();
        async move {
            Ok::<_, hyper::Error>(service_fn(move |req| {
                route(req, remote_addr, state.clone())
            }))
        }
    });

    let server = Server::bind(&addr)
        .serve(make_svc)
        .with_graceful_shutdown(async move {
            shutdown_signal.notified().await;
            eprintln!("Graceful shutdown initiated");
        });

    eprintln!("Proxy listening on {}", addr);
    if let Err(e) = server.await {
        eprintln!("Server error: {}", e);
    }
}
